const input = $input.item.json.body || $input.item.json;

const targetUrl = input.target_url || '';
const method = (input.method || 'POST').toUpperCase();
const payload = input.payload || input.body || {};
const headers = input.headers || {};
const maxRetries = Number(input.max_retries || 3);
const initialDelayMs = Number(input.initial_delay_ms || 1000);

// Compute schedule for exponential backoff with full jitter
const retrySchedule = [];
for (let i = 1; i <= maxRetries; i++) {
  const baseDelay = initialDelayMs * Math.pow(2, i - 1);
  const jitter = Math.floor(Math.random() * 250);
  retrySchedule.push({
    attempt: i,
    delay_ms: baseDelay + jitter
  });
}

return [{
  json: {
    target_url: targetUrl,
    method,
    payload,
    headers,
    max_retries: maxRetries,
    retry_schedule: retrySchedule,
    started_at: new Date().toISOString()
  }
}];
